  id: "11111111-1111-4111-8111-111111111111",
  email: "actor-a@example.test",
  full_name: "Synthetic A",
  role: "agency_admin",
  agency_id: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
